const AudioContext = window.AudioContext || window.webkitAudioContext;
        let audioCtx = null, leftOscillator = null, rightOscillator = null, leftGain = null, rightGain = null, masterGain = null, isPlaying = false, timerInterval = null, timerSeconds = 900;
        const presets = { delta: { base: 150, beat: 2 }, theta: { base: 180, beat: 6 }, alpha: { base: 200, beat: 10 }, beta: { base: 250, beat: 20 }, gamma: { base: 300, beat: 35 } };
        const baseFreqSlider = document.getElementById('baseFreq'), beatFreqSlider = document.getElementById('beatFreq'), volumeSlider = document.getElementById('volume'), baseFreqDisplay = document.getElementById('baseFreqDisplay'), beatFreqDisplay = document.getElementById('beatFreqDisplay'), volumeDisplay = document.getElementById('volumeDisplay'), playBtn = document.getElementById('playBtn'), statusIndicator = document.getElementById('status-indicator');
        baseFreqSlider.addEventListener('input', () => { baseFreqDisplay.textContent = `${baseFreqSlider.value} Hz`; if (isPlaying) updateFrequencies(); });
        beatFreqSlider.addEventListener('input', () => { beatFreqDisplay.textContent = `${beatFreqSlider.value} Hz`; if (isPlaying) updateFrequencies(); });
        volumeSlider.addEventListener('input', () => { volumeDisplay.textContent = `${volumeSlider.value}%`; if (masterGain) masterGain.gain.value = volumeSlider.value / 100 * 0.5; });
        function setPreset(presetName) { document.querySelectorAll('.preset-btn').forEach(btn => btn.classList.remove('active')); event.target.closest('.preset-btn').classList.add('active'); const preset = presets[presetName]; baseFreqSlider.value = preset.base; beatFreqSlider.value = preset.beat; baseFreqDisplay.textContent = `${preset.base} Hz`; beatFreqDisplay.textContent = `${preset.beat} Hz`; if (isPlaying) updateFrequencies(); }
        function initAudio() { if (!audioCtx) { audioCtx = new AudioContext(); masterGain = audioCtx.createGain(); masterGain.gain.value = volumeSlider.value / 100 * 0.5; masterGain.connect(audioCtx.destination); } if (audioCtx.state === 'suspended') audioCtx.resume(); }
        function togglePlay() { isPlaying ? stopAudio() : startAudio(); }
        function startAudio() { initAudio(); const baseFreq = parseFloat(baseFreqSlider.value), beatFreq = parseFloat(beatFreqSlider.value), volume = volumeSlider.value / 100 * 0.5; leftGain = audioCtx.createGain(); rightGain = audioCtx.createGain(); leftGain.gain.value = volume; rightGain.gain.value = volume; const leftPanner = audioCtx.createStereoPanner(), rightPanner = audioCtx.createStereoPanner(); leftPanner.pan.value = -1; rightPanner.pan.value = 1; leftOscillator = audioCtx.createOscillator(); rightOscillator = audioCtx.createOscillator(); leftOscillator.type = 'sine'; rightOscillator.type = 'sine'; leftOscillator.frequency.value = baseFreq; rightOscillator.frequency.value = baseFreq + beatFreq; leftOscillator.connect(leftGain); rightOscillator.connect(rightGain); leftGain.connect(leftPanner); rightGain.connect(rightPanner); leftPanner.connect(masterGain); rightPanner.connect(masterGain); leftOscillator.start(); rightOscillator.start(); isPlaying = true; playBtn.innerHTML = `<svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M21 12a9 9 0 11-18 0 9 9 0 0118 0z"></path><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 10a1 1 0 011-1h4a1 1 0 011 1v4a1 1 0 01-1 1h-4a1 1 0 01-1-1v-4z"></path></svg>Stop Session`; statusIndicator.classList.remove('hidden'); playBtn.classList.add('playing-indicator'); startVisualizer(); }
        function stopAudio() { if (leftOscillator) leftOscillator.stop(); if (rightOscillator) rightOscillator.stop(); isPlaying = false; playBtn.innerHTML = `<svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M14.752 11.168l-3.197-2.132A1 1 0 0010 9.87v4.263a1 1 0 001.555.832l3.197-2.132a1 1 0 000-1.664z"></path><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M21 12a9 9 0 11-18 0 9 9 0 0118 0z"></path></svg>Start Session`; statusIndicator.classList.add('hidden'); playBtn.classList.remove('playing-indicator'); stopVisualizer(); }
        function updateFrequencies() { const baseFreq = parseFloat(baseFreqSlider.value), beatFreq = parseFloat(beatFreqSlider.value); if (leftOscillator) leftOscillator.frequency.value = baseFreq; if (rightOscillator) rightOscillator.frequency.value = baseFreq + beatFreq; }
        function setTimer() { const minutes = prompt('Enter session duration in minutes:', '15'); if (minutes && !isNaN(minutes)) { timerSeconds = parseInt(minutes) * 60; document.getElementById('timerDisplay').classList.remove('hidden'); updateTimerDisplay(); timerInterval = setInterval(() => { timerSeconds--; updateTimerDisplay(); if (timerSeconds <= 0) { stopAudio(); cancelTimer(); alert('Session complete!'); } }, 1000); } }
        function cancelTimer() { if (timerInterval) { clearInterval(timerInterval); timerInterval = null; } timerSeconds = 900; document.getElementById('timerDisplay').classList.add('hidden'); }
        function updateTimerDisplay() { const mins = Math.floor(timerSeconds / 60), secs = timerSeconds % 60; document.getElementById('timerValue').textContent = `${mins}:${secs.toString().padStart(2, '0')}`; }
        const canvas = document.getElementById('waveCanvas'), ctx = canvas.getContext('2d'); let animationId = null;
        function startVisualizer() { canvas.width = canvas.offsetWidth * 2; canvas.height = canvas.offsetHeight * 2; drawWave(); }
        function stopVisualizer() { if (animationId) { cancelAnimationFrame(animationId); animationId = null; } ctx.clearRect(0, 0, canvas.width, canvas.height); }
        function drawWave() { if (!isPlaying) return; ctx.fillStyle = 'rgba(15, 23, 42, 0.3)'; ctx.fillRect(0, 0, canvas.width, canvas.height); const beatFreq = parseFloat(beatFreqSlider.value); ctx.beginPath(); ctx.strokeStyle = '#8b5cf6'; ctx.lineWidth = 3; for (let x = 0; x < canvas.width; x++) { const y = canvas.height / 2 + Math.sin((x + Date.now() / 10) * beatFreq / 50) * 40; if (x === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y); } ctx.stroke(); ctx.beginPath(); ctx.strokeStyle = '#ec4899'; ctx.lineWidth = 2; for (let x = 0; x < canvas.width; x++) { const y = canvas.height / 2 + Math.sin((x + Date.now() / 15) * beatFreq / 30) * 30; if (x === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y); } ctx.stroke(); animationId = requestAnimationFrame(drawWave); }
